INSERT INTO _migration_460_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_wisc_wst_b002_001', 'topic_wassce_p2_sci_wst', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'Which of the following waste items is biodegradable?', 'multiple_choice', NULL, '["A. Plastic sachet","B. Glass bottle","C. Banana peel","D. Aluminium can"]', 'C', 'A banana peel is broken down by micro-organisms within weeks, so it is biodegradable; plastic sachets, glass bottles and aluminium cans resist microbial attack and persist in the environment for decades or even centuries. Therefore the correct answer is C: Banana peel.', 'easy', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, NULL),
('q_wisc_wst_b002_002', 'topic_wassce_p2_sci_wst', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'The three Rs of waste management are', 'multiple_choice', NULL, '["A. Read, Repair and Recycle","B. Reduce, Remove and Rot","C. Reuse, Repackage and Release","D. Reduce, Reuse and Recycle"]', 'D', 'Waste management hierarchy starts with reducing what we consume, then reusing items where possible, and finally recycling materials into new products; only what remains after the three Rs should be disposed of in a controlled way. Therefore the correct answer is D: Reduce, Reuse and Recycle.', 'easy', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, NULL),
('q_wisc_wst_b002_003', 'topic_wassce_p2_sci_wst', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'Converting kitchen and garden waste into manure through controlled decomposition is called', 'multiple_choice', NULL, '["A. composting","B. incineration","C. landfilling","D. leaching"]', 'A', 'Composting is the managed aerobic decomposition of organic waste by micro-organisms into a humus-like material used as manure; incineration burns waste, landfilling buries it, and leaching is the washing out of dissolved substances. Therefore the correct answer is A: composting.', 'easy', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, NULL),
('q_wisc_wst_b002_004', 'topic_wassce_p2_sci_wst', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'The safest first step in managing household refuse is to', 'multiple_choice', NULL, '["A. burn all the waste in the backyard","B. separate biodegradable from non-biodegradable waste","C. dump the waste into the nearest gutter","D. bury all plastics in the garden"]', 'B', 'Separating waste at source keeps recyclables clean and makes organic matter available for composting. Open burning of plastics releases toxic fumes, dumping in gutters blocks drains and causes floods and disease, and buried plastics do not decompose. Therefore the correct answer is B: separate biodegradable from non-biodegradable waste.', 'easy', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, NULL),
('q_wisc_wst_b002_005', 'topic_wassce_p2_sci_wst', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'Why is the open burning of plastic waste strongly discouraged?', 'multiple_choice', NULL, '["A. It releases extra oxygen into the atmosphere","B. It makes the plastics biodegradable","C. It releases toxic fumes such as dioxins that damage health","D. It sterilises the soil for farming"]', 'C', 'Incomplete combustion of plastics emits carbon monoxide, dioxins and fine particulates linked to respiratory disease and cancer; the fumes settle on soil and crops. Burning does not make plastics biodegradable, nor does it sterilise or improve soil. Therefore the correct answer is C: It releases toxic fumes such as dioxins that damage health.', 'medium', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, NULL),
('q_wisc_wst_b002_006', 'topic_wassce_p2_sci_wst', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'The main difference between a sanitary landfill and an open refuse dump is that a sanitary landfill', 'multiple_choice', NULL, '["A. is always sited in the centre of town for easy access","B. burns all incoming waste on arrival","C. accepts only liquid waste from factories","D. is lined and the waste is covered with soil each day to control leachate and pests"]', 'D', 'An engineered sanitary landfill uses an impermeable liner to stop leachate reaching groundwater and compacts and covers the waste with soil daily to control flies, rodents and odours; an open dump leaves waste exposed to scavengers, wind and rain. Therefore the correct answer is D: is lined and the waste is covered with soil each day to control leachate and pests.', 'medium', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, NULL),
('q_wisc_wst_b002_007', 'topic_wassce_p2_sci_wst', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'Which of the following is classified as hazardous household waste?', 'multiple_choice', NULL, '["A. Used dry-cell batteries","B. Eggshells","C. Paper wrappers","D. Grass cuttings"]', 'A', 'Used dry-cell batteries contain heavy metals such as lead, cadmium and mercury which leach into soil and water and poison organisms, so they need special collection; eggshells, paper and grass cuttings are ordinary biodegradable or recyclable waste. Therefore the correct answer is A: Used dry-cell batteries.', 'medium', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, NULL),
('q_wisc_wst_b002_008', 'topic_wassce_p2_sci_wst', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'Recycling aluminium cans conserves resources mainly because', 'multiple_choice', NULL, '["A. aluminium cans cannot rust in the environment","B. remelting scrap aluminium uses far less energy than extracting new aluminium from bauxite","C. recycled aluminium is magnetic and easy to sort","D. new aluminium can no longer be mined in Ghana"]', 'B', 'Producing aluminium from bauxite is extremely energy-intensive; remelting scrap uses only a small fraction of that energy and also conserves the ore. Rusting and magnetism are irrelevant here, and bauxite mining continues, so recycling is an energy and resource saving, not a necessity. Therefore the correct answer is B: remelting scrap aluminium uses far less energy than extracting new aluminium from bauxite.', 'medium', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, NULL);
INSERT INTO _migration_460_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_460_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_460_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'wassce-int-science-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_460_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'wassce-int-science-sprint2-001', 'automated_beta', 'beta', 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.', 'https://nacca.gov.gh/secondary-education-curriculum/', 0, 1 FROM _migration_460_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_460_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_460_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 8 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_460_expected e ON e.id = r.question_id WHERE r.batch_id IS 'wassce-int-science-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 8 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_460_expected e ON e.id = q.id) = 8 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_460_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 0 THEN 1 ELSE 0 END;
